/* =====================================================================
   DPDORE — Sistema de Gestão Operacional · app.js  (v9.0)
   Gerado pela concatenação ordenada de src/01…12 (incl. 03b, 04b, 04c, 08b, 08c, 11b e 11c; ver build.sh). Secções:
     1. Utilitários (DOM, sanitização, datas, hash)          — src/01-core.js
     2. IP — toolkit de endereçamento IPv4                     — src/01-core.js
     3. Store — base de dados local, sementes, migrações       — src/01-core.js
     4. Auth — sessão, permissões, elevação, inactividade      — src/01-core.js
     5. UI — toasts, modais acessíveis, formulários            — src/02-ui.js
     6. Componentes — exportação, importação, tabela, filtros,
        gráficos interactivos, fontes de dados, widgets        — src/03-components.js
        Campos adicionais, permissões e valores ocultos dos gráficos — src/03b-custom.js
     7. Módulos — Planeador IP PMP-FO/P2P (04), PMP-FH (04b) e ajuda/esquema L3/routers/calculadora (04c),
        Painel/Planeamento/Survey (05), FWA/Stock/Constrangimentos/Gestão diária/Earth (06),
        Alertas/Relatórios/Organigrama/Listas/Utilizadores/Lixeira/Ajuda (07),
        Financeiro (08) com Facturas/AMD e anexos (08b), tabela de preços e actividades dos empreiteiros (08c),
        Viabilidade (09), Análise de cobertura (10), Cópias de segurança e Aparência (11),
        Indicadores e gráficos personalizáveis em todas as abas (11b), Lanches do Departamento (11c)
     8. Router / App (menu, aparência, exportação)             — src/05-modules-a.js
     9. Arranque                                               — src/12-boot.js
   Todas as interpolações de texto passam por esc() (prevenção de XSS).
   Não há handlers nem estilos inline: eventos delegados via data-action,
   estilos dinâmicos aplicados por CSSOM (element.style / setProperty).
   ===================================================================== */
'use strict';

/* ============ 1. UTILITÁRIOS ============ */
const $ = (sel, root = document) => root.querySelector(sel);
const $$ = (sel, root = document) => [...root.querySelectorAll(sel)];

/** Escapa texto para HTML (inclui aspas → seguro em atributos). */
const esc = (v) => String(v ?? '').replace(/[&<>"'`]/g, (c) => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;', '`': '&#96;'
}[c]));

/** Remove caracteres de controlo e limita tamanho de texto introduzido. */
const clean = (v, max = 2000) => String(v ?? '').replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '').trim().slice(0, max);

const uid = (p = 'id') => `${p}_${Date.now().toString(36)}${Math.random().toString(36).slice(2, 7)}`;
const num = (v) => { const n = Number(String(v ?? '').replace(/\s/g, '').replace(',', '.')); return Number.isFinite(n) ? n : 0; };
/** Formatadores numéricos pt-PT em cache (criar um Intl.NumberFormat por número é muito lento). */
const NF = (() => { const c = new Map(); return (o = {}) => { const k = JSON.stringify(o); let f = c.get(k); if (!f) { f = new Intl.NumberFormat('pt-PT', o); c.set(k, f); } return f; }; })();
const NF_INT = NF(); const NF_D1 = NF({ maximumFractionDigits: 1 });
const fmtInt = (n) => NF_INT.format(Math.round(num(n)));
const fmtKz = (n) => NF({ maximumFractionDigits: 0 }).format(num(n)) + ' Kz';
/** Valor monetário com cêntimos (ex.: 1 092 174 701,44 Kz). */
const fmtKz2 = (n) => NF({ minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(num(n)) + ' Kz';
/** Percentagem com casas decimais (ex.: 91,88%). */
const fmtPct = (n, d = 2) => NF({ minimumFractionDigits: d, maximumFractionDigits: d }).format(num(n)) + '%';
const todayISO = () => new Date().toISOString().slice(0, 10);
const nowISO = () => new Date().toISOString();
const debounce = (fn, ms = 250) => { let t; return (...a) => { clearTimeout(t); t = setTimeout(() => fn(...a), ms); }; };
const deepClone = (o) => JSON.parse(JSON.stringify(o));
const uniq = (a) => [...new Set(a)];
const sortPt = (a) => [...a].sort((x, y) => String(x).localeCompare(String(y), 'pt', { numeric: true }));
const countBy = (rows, key) => rows.reduce((m, r) => { const k = String(typeof key === 'function' ? key(r) : r[key] ?? '').trim() || '(vazio)'; m[k] = (m[k] || 0) + 1; return m; }, {});
const stripAccents = (s) => String(s ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const norm = (s) => stripAccents(s).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();

function parseDate(v) {
  if (!v) return null;
  if (v instanceof Date) return isNaN(v) ? null : v;
  const s = String(v).trim();
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return new Date(+m[1], +m[2] - 1, +m[3]);
  m = s.match(/^(\d{1,2})[/.-](\d{1,2})[/.-](\d{4})/);
  if (m) return new Date(+m[3], +m[2] - 1, +m[1]);
  if (/^\d{5}$/.test(s)) { const d = new Date(Math.round((+s - 25569) * 864e5)); return isNaN(d) ? null : d; } // série Excel
  return null;
}
const toISO = (d) => d ? `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}` : '';
const fmtDate = (v) => { const d = parseDate(v); return d ? d.toLocaleDateString('pt-PT') : (v ? String(v) : ''); };
const daysBetween = (a, b) => { const x = parseDate(a), y = parseDate(b) || new Date(); return x ? Math.round((y - x) / 864e5) : null; };

/** SHA-256 síncrono (as palavras-passe nunca são guardadas em texto simples). */
function sha256(ascii) {
  const rr = (v, a) => (v >>> a) | (v << (32 - a));
  const bytes = new TextEncoder().encode(ascii);
  const K = []; const H = []; let prime = 2; const isComp = {};
  for (let c = 0; c < 64; prime++) {
    if (!isComp[prime]) {
      for (let i = prime * prime; i < 313; i += prime) isComp[i] = true;
      if (c < 8) H[c] = (Math.pow(prime, .5) * 2 ** 32) | 0;
      K[c++] = (Math.pow(prime, 1 / 3) * 2 ** 32) | 0;
    }
  }
  const l = bytes.length; const words = [];
  const padded = new Uint8Array(((l + 9 + 63) >> 6) << 6); padded.set(bytes); padded[l] = 0x80;
  const bitLen = l * 8; const dv = new DataView(padded.buffer);
  dv.setUint32(padded.length - 4, bitLen >>> 0); dv.setUint32(padded.length - 8, Math.floor(bitLen / 2 ** 32));
  for (let i = 0; i < padded.length; i += 4) words.push(dv.getUint32(i));
  let hash = H.slice(0, 8);
  for (let j = 0; j < words.length; j += 16) {
    const w = words.slice(j, j + 16); const old = hash.slice(0);
    for (let i = 0; i < 64; i++) {
      const w15 = w[i - 15], w2 = w[i - 2];
      const a = hash[0], e = hash[4];
      if (i >= 16) w[i] = (w[i - 16] + (rr(w15, 7) ^ rr(w15, 18) ^ (w15 >>> 3)) + w[i - 7] + (rr(w2, 17) ^ rr(w2, 19) ^ (w2 >>> 10))) | 0;
      const t1 = hash[7] + (rr(e, 6) ^ rr(e, 11) ^ rr(e, 25)) + ((e & hash[5]) ^ (~e & hash[6])) + K[i] + w[i];
      const t2 = (rr(a, 2) ^ rr(a, 13) ^ rr(a, 22)) + ((a & hash[1]) ^ (a & hash[2]) ^ (hash[1] & hash[2]));
      hash = [(t1 + t2) | 0].concat(hash); hash[4] = (hash[4] + t1) | 0; hash.length = 8;
    }
    hash = hash.map((x, i) => (x + old[i]) | 0);
  }
  return hash.map((x) => (x >>> 0).toString(16).padStart(8, '0')).join('');
}
const pwHash = (p) => sha256('dpdore::' + String(p));

/** Só aceita imagens embutidas (data:image/…) — evita URLs arbitrários em fotografias/logótipos. */
const safeImg = (v) => (typeof v === 'string' && /^data:image\/(png|jpe?g|gif|webp|svg\+xml);base64,[a-z0-9+/=\s]+$/i.test(v) ? v : '');
/** Valida cor hexadecimal (#rrggbb). */
const colorOk = (v, fb = '') => (/^#[0-9a-f]{6}$/i.test(String(v || '')) ? v : fb);
/** Neutraliza fórmulas em exportações CSV/Excel (injecção de fórmulas). */
const cellSafe = (v) => (typeof v === 'string' && /^[=+\-@\t\r]/.test(v) && !Number.isFinite(Number(v)) ? `'${v}` : v);

/** Executa fn e devolve fallback em caso de erro (com registo na consola). */
function safe(fn, fallback = null) { try { return fn(); } catch (e) { console.error(e); return fallback; } }

/* ============ 2. IP — toolkit IPv4 ============ */
const IP = {
  toInt(ip) {
    const p = String(ip).trim().split('.');
    if (p.length !== 4 || p.some((x) => !/^\d{1,3}$/.test(x) || +x > 255)) return null;
    return ((+p[0] << 24) >>> 0) + (+p[1] << 16) + (+p[2] << 8) + +p[3];
  },
  toStr(n) { return [n >>> 24, (n >>> 16) & 255, (n >>> 8) & 255, n & 255].join('.'); },
  isIP(ip) { return IP.toInt(ip) !== null; },
  /** Interpreta "a.b.c.d/nn". Devolve {ip, prefix, net, bcast, size, hostBitsSet} ou {error}. */
  parse(cidr) {
    const s = String(cidr ?? '').trim();
    if (!s) return null;
    const m = s.match(/^(\d{1,3}(?:\.\d{1,3}){3})\s*\/\s*(\d{1,2})$/);
    if (!m) return { error: 'Formato inválido — use a.b.c.d/nn (ex.: 10.130.100.4/30)' };
    const ipn = IP.toInt(m[1]); const prefix = +m[2];
    if (ipn === null) return { error: 'Endereço IP inválido' };
    if (prefix < 8 || prefix > 32) return { error: 'Prefixo fora do intervalo /8–/32' };
    const mask = prefix === 0 ? 0 : (0xFFFFFFFF << (32 - prefix)) >>> 0;
    const net = (ipn & mask) >>> 0; const size = 2 ** (32 - prefix); const bcast = (net + size - 1) >>> 0;
    return { ip: ipn, prefix, net, bcast, size, mask, hostBitsSet: ipn !== net, cidr: `${IP.toStr(net)}/${prefix}` };
  },
  first(c) { const p = IP.parse(c); if (!p || p.error) return ''; return p.prefix >= 31 ? IP.toStr(p.net) : IP.toStr(p.net + 1); },
  second(c) { const p = IP.parse(c); if (!p || p.error) return ''; return p.prefix >= 31 ? IP.toStr(p.net + 1) : (p.size > 3 ? IP.toStr(p.net + 2) : ''); },
  hosts(c, limit = 4096) {
    const p = IP.parse(c); if (!p || p.error) return [];
    const start = p.prefix >= 31 ? p.net : p.net + 1; const end = p.prefix >= 31 ? p.bcast : p.bcast - 1;
    const out = []; for (let i = start; i <= end && out.length < limit; i++) out.push(IP.toStr(i >>> 0));
    return out;
  },
  contains(c, ip) { const p = IP.parse(c); const n = IP.toInt(ip); return !!(p && !p.error && n !== null && n >= p.net && n <= p.bcast); },
  overlaps(a, b) { const x = IP.parse(a), y = IP.parse(b); if (!x || !y || x.error || y.error) return false; return x.net <= y.bcast && y.net <= x.bcast; },
  isPrivate(c) {
    const p = IP.parse(c); const n = p && !p.error ? p.net : IP.toInt(c); if (n === null || n === undefined) return false;
    const inR = (base, pre) => { const b = IP.toInt(base); const m = (0xFFFFFFFF << (32 - pre)) >>> 0; return ((n & m) >>> 0) === b; };
    return inR('10.0.0.0', 8) || inR('172.16.0.0', 12) || inR('192.168.0.0', 16) || inR('100.64.0.0', 10);
  }
};

