function defaultPerms(level) {
  const adminOnly = ['lists', 'users', 'trash'];
  const readOnly = ['finance', 'alerts', 'help', 'appearance', 'backup'];
  const p = {};
  MODULES.forEach(([id]) => {
    if (level === 'admin') p[id] = { view: true, edit: true, del: true };
    else if (adminOnly.includes(id)) p[id] = { view: false, edit: false, del: false };
    else p[id] = { view: true, edit: !readOnly.includes(id), del: false };
  });
  return p;
}

