  if (Array.isArray(old.stock) && old.stock.length && old.stock[0]?.items) {
    db.stock.items = old.stock.flatMap((c) => (c.items || []).map((it) => ({ id: uid('st'), fornecedor: c.category, item: it[0], qtd: num(it[1]), min: 5, armazem: 'Central', unidade: 'un' })));
  }
