    d.settings.nav = d.settings.nav || {};
    d.widgets = { ...f.widgets, ...d.widgets };
    d.coverage = { sites: [], ...(d.coverage || {}) };
    d.finance = { po: [], monthly: [], weekly: [], docs: [], allocs: [], prices: [], acts: [], ...(d.finance || {}) };
    d.snacks = { people: [], events: [], ...(d.snacks || {}) }; d.snacks.settings = { ...SNACK_DEFAULTS, ...(d.snacks.settings || {}) };
    d.kpiPrefs = d.kpiPrefs || {}; d.customKpis = d.customKpis || {}; d.settings.customFields = d.settings.customFields || {};
    d.settings.fh = d.settings.fh || {}; d.settings.amd = { iva: 14, retencao: 0, basis: 'total', ...(d.settings.amd || {}) };
    d.meta = { ...f.meta, ...(d.meta || {}) };
    // Registos criados antes da v8.1 em colecções com chave "id" (VRF, organigrama) recebem o "id" em falta.
    ['vrfs', 'org'].forEach((k) => (d[k] || []).forEach((r) => { if (!r.id && r._id) r.id = r._id; }));
    (d.stock?.items || []).forEach((r) => { if (!r.id) r.id = r._id || uid('st'); });
    if (!d.migrations.includes('v81-perms')) {
      // Abas novas: administradores com acesso total; restantes utilizadores só com consulta (o administrador decide quem edita).
      (d.users || []).forEach((u) => { u.perms = u.perms || {}; MODULES.forEach(([id]) => { if (u.perms[id]) return; const def = defaultPerms(u.role === 'admin' ? 'admin' : 'user')[id]; u.perms[id] = u.role === 'admin' ? def : { view: def.view, edit: false, del: false }; }); if (u.role !== 'admin') u.perms.appearance = { view: true, edit: false, del: false }; });
      d.migrations.push('v81-perms');
    }
    if (!d.migrations.includes('v83-perms')) {
      // V8.3: nova aba "Lanches do Departamento" — todos consultam; o administrador edita e decide quem mais edita.
      (d.users || []).forEach((u) => { u.perms = u.perms || {}; MODULES.forEach(([id]) => { if (u.perms[id]) return; const def = defaultPerms(u.role === 'admin' ? 'admin' : 'user')[id] || { view: true, edit: false, del: false }; u.perms[id] = u.role === 'admin' ? def : { view: true, edit: false, del: false }; }); });
      d.migrations.push('v83-perms');
    }
