    const req = f.required ? ' required aria-required="true"' : '';
    const common = `id="${id}" name="${esc(f.key)}"${req}${f.placeholder ? ` placeholder="${esc(f.placeholder)}"` : ''}${f.autocomplete ? ` autocomplete="${esc(f.autocomplete)}"` : ''}`;
    let ctl = '';
