/* ---- 5) Google Earth: nova apresentação (indicadores, pastas com cores, mapa com grelha, tabela com atalhos) ---- */
const EarthUI = {
  folder: '',
  pal() { return typeof PAL !== 'undefined' && Array.isArray(PAL) ? PAL : ['#25354f', '#0f8a7e', '#f28b28', '#5b2a86', '#c8372d', '#6b7fa3', '#b97f00', '#2f7fbf']; },
  valid(p) { return p.lat !== '' && p.lat !== null && Number.isFinite(+p.lat) && Number.isFinite(+p.lon) && Math.abs(+p.lat) <= 90 && Math.abs(+p.lon) <= 180; },
  map(pts, colorOf) {
    const W = 640, H = 460, P = 34;
    let b = { lat0: -18.2, lat1: -4.2, lon0: 11.4, lon1: 24.3 };
    if (pts.length) { b = { lat0: Math.min(...pts.map((p) => +p.lat)), lat1: Math.max(...pts.map((p) => +p.lat)), lon0: Math.min(...pts.map((p) => +p.lon)), lon1: Math.max(...pts.map((p) => +p.lon)) };
      const pad = (a, z) => { const d = Math.max(0.02, (b[z] - b[a]) * 0.08); b[a] -= d; b[z] += d; }; pad('lat0', 'lat1'); pad('lon0', 'lon1'); }
    const sx = (lon) => P + ((lon - b.lon0) / (b.lon1 - b.lon0)) * (W - 2 * P); const sy = (lat) => P + ((b.lat1 - lat) / (b.lat1 - b.lat0)) * (H - 2 * P);
    const span = Math.max(b.lat1 - b.lat0, b.lon1 - b.lon0); const step = [0.01, 0.02, 0.05, 0.1, 0.25, 0.5, 1, 2, 5].find((s) => span / s <= 8) || 5;
    const dec = step < 0.1 ? 2 : step < 1 ? 1 : 0; const grid = [];
    for (let v = Math.ceil(b.lon0 / step) * step; v <= b.lon1; v += step) grid.push(`<line class="gr" x1="${sx(v).toFixed(1)}" y1="${P}" x2="${sx(v).toFixed(1)}" y2="${H - P}"/><text class="gl" x="${sx(v).toFixed(1)}" y="${H - P + 16}" text-anchor="middle">${v.toFixed(dec)}°</text>`);
    for (let v = Math.ceil(b.lat0 / step) * step; v <= b.lat1; v += step) grid.push(`<line class="gr" x1="${P}" y1="${sy(v).toFixed(1)}" x2="${W - P}" y2="${sy(v).toFixed(1)}"/><text class="gl" x="${P - 6}" y="${(sy(v) + 4).toFixed(1)}" text-anchor="end">${v.toFixed(dec)}°</text>`);
    return `<svg class="map earth-map" viewBox="0 0 ${W} ${H}" role="img" aria-label="Mapa com ${pts.length} pontos (grelha de latitude e longitude)">
      <rect class="bg" x="${P}" y="${P}" width="${W - 2 * P}" height="${H - 2 * P}" rx="6"/>${grid.join('')}
      ${pts.slice(0, 3000).map((p) => `<circle class="ept" cx="${sx(+p.lon).toFixed(1)}" cy="${sy(+p.lat).toFixed(1)}" r="5" fill="${colorOf(p)}"><title>${esc(p.nome)} · ${esc(p.pasta || '')} (${(+p.lat).toFixed(5)}, ${(+p.lon).toFixed(5)})</title></circle>`).join('')}
      <text class="gl n" x="${W - P - 4}" y="${P + 16}" text-anchor="end">N ↑</text></svg>`;
  }
};
