  const toolbar = `<div class="toolbar earth-toolbar">${canE ? '<button class="btn primary" data-action="earth-import">Importar KML/KMZ</button><button class="btn" data-action="earth-surveys">Carregar coordenadas dos surveys</button><button class="btn" data-action="crud-add" data-path="earth">+ Ponto</button>' : ''}
      <span class="spacer"></span><button class="btn" data-action="earth-kml">Exportar KML</button><button class="btn" data-action="export-src" data-src="earth" data-name="Pontos">Exportar Excel</button></div>`;
