const ensureListsV85 = () => { if (typeof DB === 'undefined' || !DB || !DB.lists) return; Object.entries(LIST_DEF_V85).forEach(([k, d]) => { if (!Array.isArray(DB.lists[k])) DB.lists[k] = [...d]; }); };
