      body += T(36, 56, `SITE_ID – ${d.siteId || '…'}`, 'nd-h', 'start') + T(36, 80, d.lo ? `IP_Lo64: ${d.lo}` : 'IP_Lo64: …', 'nd-h2', 'start') + T(736, 86, `CLIENTE_ID – ${d.cliId || '…'}`, 'nd-h', 'start') + T(736, 108, `IP_Lo64: ${d.cliLo || '…'}`, 'nd-h2', 'start');
      body += `<path class="nd-link nd-fo" d="M190 190 H1040"/>${I.router(140, 190, 1.2)}${I.conv(520, 190)}${I.conv(790, 190)}${I.router(1060, 190, 0.85)}`;
      body += T(140, 150, d.site, 'nd-name') + T(1060, 160, d.cpe, 'nd-name') + T(240, 214, d.ifSite, 'nd-if') + T(985, 214, d.ifCpe, 'nd-if');
      const lines = (side) => [`O&M ${side === 's' ? d.omSite || '' : d.omCpe || ''}${C.vlans && d.omVlan ? ` VLAN ${d.omVlan}` : ''}`, ...d.svc.map((s) => `${s.tag} ${side === 's' ? (s.site || (s.agg && IP.first(s.agg)) || '') : s.cpe || ''}${C.vlans && (s.vlan || s.aggVlan) ? ` VLAN ${s.aggVlan || s.vlan}` : ''}`)];
      const box = (x, y, side) => `<rect class="nd-info" x="${x}" y="${y}" width="200" height="${16 + lines(side).length * 14}" rx="3"/>${lines(side).map((l, i) => T(x + 100, y + 14 + i * 14, l, 'nd-small')).join('')}`;
      body += C.ips ? box(300, 158, 's') + box(830, 158, 'c') : '';
