  /** Linhas com o próximo aniversário (datas pessoais do perfil do organigrama). */
  rows() {
    const today = new Date(); today.setHours(0, 0, 0, 0);
    const next = (d) => { if (!d) return null; let x = new Date(today.getFullYear(), d.getMonth(), d.getDate()); if (x < today) x = new Date(today.getFullYear() + 1, d.getMonth(), d.getDate()); return x; };
    return DB.org.map((o) => {
      const d = parseDate(o.dataNascimento); const nx = next(d); const adm = parseDate(o.dataAdmissao); const cas = parseDate(o.dataCasamento);
      return { o, d, nx, dias: nx ? Math.round((nx - today) / 864e5) : null, faz: nx && d ? nx.getFullYear() - d.getFullYear() : null, idade: d ? Math.floor((today - d) / (365.2425 * 864e5)) : null,
        mes: d ? d.getMonth() : null, casa: adm ? Math.floor((today - adm) / (365.2425 * 864e5)) : null, adm, cas };
    });
  },
  flat(x) {
    return { _id: x.o.id, Nome: x.o.nome, 'Função': x.o.funcao || '', 'Secção': x.o.categoria || '', 'Data de nascimento': x.d ? fmtDate(toISO(x.d)) : '', Idade: x.idade ?? '',
      'Próximo aniversário': x.nx ? x.nx.toLocaleDateString('pt-PT', { weekday: 'long', day: 'numeric', month: 'long' }) : '', 'Faz (anos)': x.faz ?? '', 'Faltam (dias)': x.dias ?? '',
      'Mês': x.mes === null ? '(sem data)' : MESES_PT[x.mes], 'Entrada na empresa': x.adm ? fmtDate(toISO(x.adm)) : '', 'Anos de casa': x.casa ?? '', 'Data de casamento': x.cas ? fmtDate(toISO(x.cas)) : '', Telefone: x.o.telefone || '', Email: x.o.email || '' };
  },
