/* ---- 4) FWA: importação do ficheiro de clientes com ajuste (colunas, edição em massa, chave ID ou cliente) ---- */
const FwaX = {
  fields() { return uniq([...FWA_FIELDS, ...DB.fwa.records.slice(0, 3000).flatMap((r) => Object.keys(r))]).filter((k) => !k.startsWith('_') && k !== 'id'); },
  cols() { const all = FwaX.fields(); const c = (DB.tablePrefs.fwaCols || []).filter((k) => all.includes(k)); return c.length ? c : FWA_FIELDS.slice(0, 9); },
  /** Normaliza uma linha importada/colada (datas ISO, números, província da lista, ano pela data). */
  normRow(r) {
    const o = { ...r };
    if (o['Data de activação']) o['Data de activação'] = toISO(parseDate(o['Data de activação'])) || o['Data de activação'];
    if (o['Largura de banda (Mbps)'] !== undefined && o['Largura de banda (Mbps)'] !== '') o['Largura de banda (Mbps)'] = num(String(o['Largura de banda (Mbps)']).replace(/mbps/i, ''));
    if (!o.Ano && o['Data de activação']) { const d = parseDate(o['Data de activação']); if (d) o.Ano = d.getFullYear(); }
    if (o.Ano !== undefined && o.Ano !== '') o.Ano = Math.round(num(o.Ano)) || o.Ano;
    if (o['Província']) { const p = DB.lists.provinces.find((x) => norm(x.nome) === norm(o['Província']) || norm(x.codigo) === norm(o['Província'])); o['Província'] = p ? p.nome : clean(o['Província'], 40).toUpperCase(); }
    if (o['Serviço']) o['Serviço'] = clean(o['Serviço'], 30).toUpperCase();
    if (o.Estado) { const e = ['Activo', 'Em instalação', 'Suspenso', 'Cancelado'].find((x) => norm(x) === norm(o.Estado)); if (e) o.Estado = e; }
    return o;
  },
  /** Aplica a importação: actualiza pelo ID (ou, sem ID, pelo nome do cliente/site). */
  apply(rows, mode) {
    let added = 0, updated = 0, skipped = 0; const R = DB.fwa.records;
    if (mode === 'replace') R.length = 0;
    rows.map(FwaX.normRow).forEach((r) => {
      const id = String(r.ID ?? '').trim(); const cli = String(r['Cliente / Site'] ?? '').trim();
      if (!id && !cli) { skipped++; return; }
      const idx = mode === 'upsert' ? R.findIndex((x) => (id ? String(x.ID ?? '').trim() === id : norm(x['Cliente / Site']) === norm(cli))) : -1;
      if (idx >= 0) { R[idx] = { ...R[idx], ...r }; updated++; } else { R.push({ _id: uid('fw'), ...r }); added++; }
    });
    return { added, updated, skipped, reason: 'linhas sem ID nem cliente/site' };
  }
};
