        if (fmt === 'pptx' || fmt === 'pptx-img') await Deck.pptx(list, fmt === 'pptx' ? 'native' : 'img');
        else if (fmt === 'pdf') Deck.pdf(list); else if (fmt === 'docx') await Deck.docx(list);
        else if (fmt === 'jpg' || fmt === 'png') await Deck.images(list, fmt === 'png' ? 'image/png' : 'image/jpeg'); else Deck.xlsx(list);
        Store.log(`Apresentação exportada (${fmt}, ${ids.length} diapositivos)`, 'reports'); Store.save(); m.close(); UI.toast('Exportação concluída.');
        if (admin && $('[data-keep]', host)?.checked) App.rerender();
