/* ============ 11w. V9.0 — PASTA DAS CÓPIAS DE SEGURANÇA (ARRANQUE), DUPLICADOS NO RESTAURO, PARTILHAR / INSTALAR ============
   · Pasta das cópias (Chrome / Edge no computador; ex.: pasta do OneDrive / SharePoint): o sistema grava aí cópias
     completas automaticamente e, no arranque, procura a mais recente — restaura sozinho (fusão) ou pergunta.
   · Sem pasta ligada: pode perguntar no arranque se quer procurar uma cópia de segurança.
   · Restauro: mostra antes, por módulo, o que é novo, o que vai ser actualizado e o que é igual (não duplicado);
     o administrador pode, se preferir, permitir duplicados.
   · Partilhar a aplicação: ligação, e-mail, WhatsApp, partilha do sistema e instalação (PWA na versão publicada).
   · O armazenamento não tem limite fixo: depende do espaço livre do computador (IndexedDB + pedido de persistência). */

// as abas próprias entram nas cópias de segurança
BACKUP_PARTS.push(['custom', 'Abas próprias criadas pelo administrador (registos)', ['custom']]);
BACKUP_SHAPE.custom = 'o';

const BkDir = {
  handle: null, perm: 'none', name: '', timer: null, lastWrite: 0, busy: false,
  supported() { return typeof window.showDirectoryPicker === 'function'; },
  cfg() { return { startup: 'ask-newer', every: 30, keep: 20, files: false, ...(DB.settings.bkDir || {}) }; },
  device() { let d = safe(() => localStorage.getItem('dpdore_device')); if (!d) { d = uid('pc'); safe(() => localStorage.setItem('dpdore_device', d)); } return d; },
  async init() {
    if (!BkDir.supported()) return; const rec = await StoreX.get('bkDir').catch(() => null); if (!rec?.handle) return;
    BkDir.handle = rec.handle; BkDir.name = rec.handle.name || ''; try { BkDir.perm = await rec.handle.queryPermission({ mode: 'readwrite' }); } catch (_) { BkDir.perm = 'prompt'; }
  },
  async connect() {
    if (!BkDir.supported()) { UI.toast('Este navegador não permite escolher uma pasta. Use o Google Chrome ou o Microsoft Edge no computador.', 'warn', 7000); return; }
    try { const h = await window.showDirectoryPicker({ id: 'dpdore-copias', mode: 'readwrite' }); BkDir.handle = h; BkDir.name = h.name; BkDir.perm = 'granted';
      await StoreX.put({ id: 'bkDir', handle: h, name: h.name }); Store.log(`Pasta das cópias ligada: ${h.name}`, 'backup'); Store.save(); await BkDir.write(true); App.rerender(); }
    catch (e) { if (e.name !== 'AbortError') UI.toast(`Pasta não ligada: ${e.message}`, 'error'); }
  },
  async off() { BkDir.handle = null; BkDir.perm = 'none'; await StoreX.del('bkDir').catch(() => {}); Store.log('Pasta das cópias desligada', 'backup'); App.rerender(); },
  async reauth() { if (!BkDir.handle) return false; try { BkDir.perm = await BkDir.handle.requestPermission({ mode: 'readwrite' }); } catch (_) { BkDir.perm = 'denied'; } App.rerender(); return BkDir.perm === 'granted'; },
  on() { return !!BkDir.handle && BkDir.perm === 'granted'; },
  /** Lista as cópias DPDORE da pasta (mais recente primeiro). */
  async list() {
    if (!BkDir.on()) return []; const out = [];
    for await (const [name, h] of BkDir.handle.entries()) { if (h.kind !== 'file' || !/^DPDORE_.*\.json$/i.test(name)) continue; try { const f = await h.getFile(); out.push({ name, h, f, at: f.lastModified }); } catch (_) { /* ilegível */ } }
    return out.sort((a, b) => b.at - a.at);
  },
  /** Grava uma cópia completa na pasta e apaga as mais antigas (mantém as últimas N). */
  async write(force = false) {
    if (!BkDir.on() || BkDir.busy) return; const C = BkDir.cfg(); if (!force && Date.now() - BkDir.lastWrite < C.every * 60000) return;
    BkDir.busy = true;
    try {
      const env = Backup.envelope(BACKUP_PARTS.map((p) => p[0])); env.device = BkDir.device(); env.release = '9.0';
      if (C.files) { try { env.data.files = await Files.exportAll(); } catch (_) { /* sem anexos */ } }
      const name = `DPDORE_copia_${Exporter.stamp()}_${(Auth.user?.user || 'sistema').replace(/[^a-z0-9]/gi, '')}.json`;
      const fh = await BkDir.handle.getFileHandle(name, { create: true }); const w = await fh.createWritable(); await w.write(JSON.stringify(env)); await w.close();
      BkDir.lastWrite = Date.now(); DB.meta.lastFolderBackup = nowISO();
      const L = await BkDir.list(); for (const x of L.slice(Math.max(1, C.keep))) { try { await BkDir.handle.removeEntry(x.name); } catch (_) { /* sem permissão para apagar */ } }
      if (force) UI.toast(`Cópia gravada na pasta «${BkDir.name}».`);
    } catch (e) { console.error(e); if (e.name === 'NotAllowedError') BkDir.perm = 'prompt'; UI.toast(`Não foi possível gravar na pasta das cópias: ${e.message}`, 'warn', 7000); }
    finally { BkDir.busy = false; }
  },
  schedule() { clearTimeout(BkDir.timer); BkDir.timer = setTimeout(() => BkDir.write(false), 4000); },
  /** No arranque: procura uma cópia mais recente na pasta (ou pergunta se quer procurar). */
  async startup() {
    if (Auth.user?.mustChange) { setTimeout(() => BkDir.startup().catch(() => {}), 2500); return; } // primeiro a mudança da palavra-passe
    const C = BkDir.cfg(); if (!Auth.isAdmin() || C.startup === 'none' || sessionStorage.getItem('dpdore_bk_checked')) return; sessionStorage.setItem('dpdore_bk_checked', '1');
    if (BkDir.handle && BkDir.perm !== 'granted') { BkDir.askAuth(); return; }
    if (!BkDir.on()) { if (C.startup === 'ask-always' || (C.startup === 'ask-newer' && !DB.settings.bkDir?.asked)) { DB.settings.bkDir = { ...C, asked: true }; Store.save(); BkDir.askSearch(); } return; }
    const L = await BkDir.list(); const mine = BkDir.device(); const localAt = Date.parse(StoreX.at || DB.meta?.lastSaved || 0) || 0;
    for (const x of L.slice(0, 5)) {
      let env; try { env = JSON.parse(await x.f.text()); } catch (_) { continue; }
      if (env.device === mine) return; // a mais recente é deste computador: nada a fazer
      if (x.at <= localAt) return;
      const parsed = safe(() => Backup.parse(env)); if (!parsed) continue;
      if (C.startup === 'auto') { UI.toast(`Cópia mais recente encontrada na pasta («${x.name}»): a fundir…`, 'ok', 5000); await Backup.apply(parsed.data, parsed.parts.filter((p) => p !== 'users'), 'merge', true, parsed.kind, parsed.meta); return; }
      const m = UI.modal({ title: 'Cópia mais recente na pasta', size: 'narrow', body: `<p>Na pasta <b>${esc(BkDir.name)}</b> há uma cópia mais recente do que os dados deste computador:</p><p class="note">${esc(x.name)} · ${esc(new Date(x.at).toLocaleString('pt-PT'))}${env.exportedBy ? ` · por ${esc(env.exportedBy)}` : ''}<br>${esc(Backup.summary(parsed.data))}</p><p>Quer ver o que muda e actualizar este computador?</p>`,
        foot: '<button class="btn" type="button" data-close>Agora não</button><button class="btn primary" type="button" data-go>Ver e actualizar…</button>' });
      $('[data-go]', m.el).onclick = () => { m.close(); Backup.dialog(parsed, `pasta ${BkDir.name} · ${x.name}`); };
      return;
    }
  },
  askAuth() {
    const m = UI.modal({ title: 'Pasta das cópias de segurança', size: 'narrow', body: `<p>O navegador precisa de autorização para voltar a usar a pasta <b>${esc(BkDir.name)}</b> (onde ficam as cópias e as actualizações).</p>`,
      foot: '<button class="btn" type="button" data-close>Agora não</button><button class="btn primary" type="button" data-go>Autorizar</button>' });
    $('[data-go]', m.el).onclick = async () => { m.close(); if (await BkDir.reauth()) { sessionStorage.removeItem('dpdore_bk_checked'); BkDir.startup(); } };
  },
  askSearch() {
    const m = UI.modal({ title: 'Procurar uma cópia de segurança?', size: 'narrow', body: '<p>Pretende procurar uma cópia de segurança com as alterações mais recentes (por exemplo, feitas noutro computador)?</p><p class="muted">Pode também ligar uma pasta (OneDrive / SharePoint) onde o sistema grava e procura as cópias sozinho.</p>',
      foot: `<button class="btn left" type="button" data-never>Não perguntar mais</button><button class="btn" type="button" data-close>Agora não</button>${BkDir.supported() ? '<button class="btn" type="button" data-dir>Ligar pasta…</button>' : ''}<button class="btn primary" type="button" data-file>Escolher ficheiro…</button>` });
    $('[data-never]', m.el).onclick = () => { DB.settings.bkDir = { ...BkDir.cfg(), startup: 'none' }; Store.save(); m.close(); };
    $('[data-file]', m.el).onclick = () => { m.close(); Backup.importFile(); };
    $('[data-dir]', m.el)?.addEventListener('click', async () => { m.close(); await BkDir.connect(); sessionStorage.removeItem('dpdore_bk_checked'); BkDir.startup(); });
  },
  panel() {
    const C = BkDir.cfg(); const st = !BkDir.supported() ? ['muted', 'Este navegador não permite pastas (use Chrome ou Edge no computador).'] : !BkDir.handle ? ['muted', 'Nenhuma pasta ligada.'] : BkDir.perm === 'granted' ? ['ok', `Ligada: «${BkDir.name}»${DB.meta?.lastFolderBackup ? ` · última cópia ${new Date(DB.meta.lastFolderBackup).toLocaleString('pt-PT')}` : ''}`] : ['warn', `«${BkDir.name}» — falta autorizar`];
    return `<section class="panel mt-16 bkdir" aria-labelledby="bkdH"><div class="panel-head"><h3 id="bkdH">Pasta das cópias e actualizações no arranque</h3>
      <p>As cópias completas são gravadas automaticamente nesta pasta (ex.: OneDrive / SharePoint partilhado). Ao abrir o sistema, procura-se a cópia mais recente feita noutro computador.</p></div>
      <p class="bkdir-st ${st[0]}">${esc(st[1])}</p>
      <div class="toolbar m-0">${BkDir.handle ? `${BkDir.perm !== 'granted' ? '<button class="btn primary" data-action="bkd-auth">Autorizar pasta</button>' : '<button class="btn" data-action="bkd-now">Gravar cópia agora</button><button class="btn" data-action="bkd-check">Procurar actualizações agora</button>'}<button class="btn ghost" data-action="bkd-off">Desligar pasta</button>`
        : `<button class="btn primary" data-action="bkd-connect"${BkDir.supported() ? '' : ' disabled'}>Ligar pasta das cópias…</button>`}<button class="btn" data-action="bkd-cfg">Opções…</button></div>
      <p class="field-help">No arranque: <b>${esc({ 'ask-newer': 'perguntar quando houver uma cópia mais recente', 'ask-always': 'perguntar sempre se quer procurar uma cópia', auto: 'actualizar automaticamente (fusão, sem duplicar)', none: 'não procurar' }[C.startup] || C.startup)}</b> · cópia a cada ${C.every} min de trabalho · mantém as últimas ${C.keep}.</p>
      <p class="field-help">Armazenamento: sem limite fixo — depende do espaço livre do computador (base de dados do navegador${StoreX.persisted ? ', protegida contra limpeza' : ''}).</p></section>`;
  },
  options() {
    Auth.requireAdmin(() => { const C = BkDir.cfg();
      UI.form({ title: 'Opções da pasta das cópias', size: 'narrow', values: C,
        fields: [{ key: 'startup', label: 'No arranque do sistema', type: 'select', required: true, options: [{ value: 'ask-newer', label: 'Perguntar quando houver uma cópia mais recente' }, { value: 'ask-always', label: 'Perguntar sempre se quer procurar uma cópia' }, { value: 'auto', label: 'Actualizar automaticamente (fusão, sem duplicar)' }, { value: 'none', label: 'Não procurar' }] },
          { key: 'every', label: 'Gravar uma cópia a cada (minutos de trabalho)', type: 'number', min: 5, max: 1440 }, { key: 'keep', label: 'Cópias a manter na pasta', type: 'number', min: 1, max: 500 },
          { key: 'files', label: 'Incluir os anexos (facturas e AMD) nas cópias da pasta', type: 'checkbox' }],
        onSubmit: (v) => { const every = Math.round(num(v.every)), keep = Math.round(num(v.keep)); if (every < 5 || every > 1440) return 'Intervalo entre 5 e 1440 minutos.'; if (keep < 1 || keep > 500) return 'Mantenha entre 1 e 500 cópias.';
          DB.settings.bkDir = { startup: v.startup, every, keep, files: !!v.files, asked: true }; Store.save(); App.rerender(); return true; } });
    }, 'As opções das cópias exigem a palavra-passe de administrador.');
  }
};
{
  // grava na pasta depois das alterações (com intervalo mínimo) e procura actualizações depois de entrar
  const save0 = Store.save.bind(Store); Store.save = (...a) => { const r = save0(...a); if (BkDir.on()) BkDir.schedule(); return r; };
  const p0 = StoreX.preload.bind(StoreX); StoreX.preload = async (...a) => { const r = await p0(...a); await BkDir.init().catch(() => {}); return r; };
  const l0 = Auth.login.bind(Auth); Auth.login = (u, p) => { const r = l0(u, p); if (r === true) setTimeout(() => BkDir.startup().catch((e) => console.warn(e)), 900); return r; };
  const rs0 = Auth.restore.bind(Auth); Auth.restore = () => { const r = rs0(); if (r) setTimeout(() => BkDir.startup().catch((e) => console.warn(e)), 1200); return r; };
  const V = App.views.backup; const r0 = V.render.bind(V);
  V.render = () => { const h = r0(); return h.replace('<div class="grid c2">', `<div class="toolbar"><button class="btn" data-action="app-share">Partilhar / instalar a aplicação</button></div><div class="grid c2">`) + BkDir.panel(); };
  Object.assign(App.actions, {
    'bkd-connect': () => Auth.requireAdmin(() => BkDir.connect(), 'Ligar a pasta das cópias exige a palavra-passe de administrador.'),
    'bkd-off': () => Auth.requireAdmin(() => BkDir.off()), 'bkd-auth': () => BkDir.reauth(), 'bkd-now': () => BkDir.write(true), 'bkd-cfg': () => BkDir.options(),
    'bkd-check': () => { sessionStorage.removeItem('dpdore_bk_checked'); const c = BkDir.cfg(); const prev = c.startup; DB.settings.bkDir = { ...c, startup: prev === 'auto' ? 'auto' : 'ask-newer' };
      BkDir.startup().then(() => setTimeout(() => { if (!UI.stack.length) UI.toast('Não há cópias mais recentes de outros computadores na pasta.'); }, 400)).finally(() => { DB.settings.bkDir = { ...DB.settings.bkDir, startup: prev }; }); }
  });
}

/* ---- Restauro: o que é novo / actualizado / igual, por módulo; duplicados só se o administrador quiser ---- */
const BkDiff = {
  /** Conta registos novos, alterados e iguais entre a base actual e a cópia (listas, mesmo dentro de objectos). */
  diff(cur, inc, path = '', out = { add: 0, upd: 0, same: 0, samples: [] }) {
    if (Array.isArray(inc)) {
      if (!inc.length || inc.every((x) => x === null || typeof x !== 'object')) return out;
      const bk = MERGE_KEYS[path]; const C = Array.isArray(cur) ? cur : [];
      const keyOf = (r) => { if (!r || typeof r !== 'object') return null; const k = bk ? r[bk] : (r.id ?? r._id); return k === undefined || k === null || k === '' ? null : String(k).toLowerCase(); };
      const byKey = new Map(); C.forEach((r) => { const k = keyOf(r); if (k !== null) byKey.set(k, r); }); const sigs = new Set(C.map(Backup.canon));
      inc.forEach((r) => { const k = keyOf(r); const s = Backup.canon(r);
        if (sigs.has(s)) out.same++; else if (k !== null && byKey.has(k)) out.upd++; else { out.add++; if (out.samples.length < 4) out.samples.push(BkDiff.label(r)); } });
      return out;
    }
    if (inc && typeof inc === 'object') Object.keys(inc).forEach((k) => BkDiff.diff(cur && typeof cur === 'object' ? cur[k] : undefined, inc[k], path ? `${path}.${k}` : k, out));
    return out;
  },
  label(r) { const k = ['NOME CLIENTE', 'nome', 'cliente', 'item', 'po', 'user', 'titulo', 'ID', 'id'].find((x) => r[x]); return k ? String(r[k]).slice(0, 40) : '(registo)'; }
};
{
  const dlg0 = Backup.dialog.bind(Backup);
  Backup.dialog = (parsed, source) => {
    dlg0(parsed, source); const m = UI.stack[UI.stack.length - 1]; if (!m) return;
    const { data, parts } = parsed;
    const rows = BACKUP_PARTS.filter((p) => parts.includes(p[0]) && p[0] !== 'files').map((p) => { const o = { add: 0, upd: 0, same: 0, samples: [] }; p[2].forEach((k) => data[k] !== undefined && BkDiff.diff(DB[k], data[k], k, o)); return { p, ...o }; });
    const box = document.createElement('div'); box.className = 'bk-diff mt-12';
    box.innerHTML = `<h4 class="h4 m-0">O que muda (antes de aplicar)</h4><div class="table-wrap mt-8"><table><caption class="sr-only">Diferenças por módulo</caption><thead><tr><th scope="col">Módulo</th><th scope="col" class="num">Novos (adicionados)</th><th scope="col" class="num">Alterados (actualizados)</th><th scope="col" class="num">Iguais (não duplicados)</th><th scope="col">Exemplos de novos</th></tr></thead>
      <tbody>${rows.map((r) => `<tr><td>${esc(r.p[1])}</td><td class="num">${fmtInt(r.add)}</td><td class="num">${fmtInt(r.upd)}</td><td class="num">${fmtInt(r.same)}</td><td class="muted">${esc(r.samples.join(', '))}</td></tr>`).join('')}</tbody></table></div>
      ${Auth.isAdmin() ? '<label class="inline mt-8"><input type="checkbox" data-bk-dup> Permitir duplicados: adicionar os registos da cópia como novos, mesmo os que já existem (só se tiver a certeza)</label>' : ''}`;
    $('fieldset', m.body)?.after(box);
    const dup = $('[data-bk-dup]', box);
    dup?.addEventListener('change', () => { $$('input[name=bkmode]', m.el).forEach((r) => { r.disabled = dup.checked; }); });
    // modo «duplicar»: antes do restauro, passa a acrescentar em vez de fundir
    $('[data-go]', m.el)?.addEventListener('click', () => { Backup._dup = !!dup?.checked; }, true);
  };
  const merge0 = Backup.merge.bind(Backup);
  Backup.merge = (cur, inc, path = '') => {
    if (Backup._dup && Array.isArray(inc) && Array.isArray(cur) && inc.some((x) => x && typeof x === 'object')) return [...cur, ...inc.map((r) => (r && typeof r === 'object' ? { ...r, ...(r._id ? { _id: uid('dup') } : {}) } : r))];
    return merge0(cur, inc, path);
  };
  const ap0 = Backup.apply.bind(Backup);
  Backup.apply = async (data, parts, mode, keep, kind, meta) => { try { return await ap0(data, parts, Backup._dup ? 'merge' : mode, keep, kind, meta); } finally { Backup._dup = false; } };
}

/* ---- Partilhar e instalar a aplicação ---- */
const AppShare = {
  deferred: null,
  url() { return /^https?:$/.test(location.protocol) ? location.href.split('#')[0] : ''; },
  open() {
    const u = AppShare.url(); const canShare = typeof navigator.share === 'function';
    const msg = `${DB.settings.brand || 'DPDORE'} — Sistema de Gestão Operacional${u ? `: ${u}` : ''}`;
    const m = UI.modal({ title: 'Partilhar e instalar a aplicação', size: 'narrow',
      body: `${u ? `<label for="shu">Ligação da aplicação</label><div class="flex"><input id="shu" readonly value="${esc(u)}"><button type="button" class="btn" data-copy>Copiar</button></div>` : '<p class="note">Está a usar o ficheiro .html no computador. Para partilhar, envie o próprio ficheiro (anexo de e-mail, Teams, WhatsApp ou pasta partilhada) — funciona sem internet. Para instalar como aplicação, publique a pasta «ficheiros separados» (GitHub Pages / SharePoint) e partilhe a ligação.</p>'}
        <div class="toolbar mt-12">${canShare ? '<button type="button" class="btn primary" data-share>Partilhar…</button>' : ''}<a class="btn" data-mail href="mailto:?subject=${encodeURIComponent('Aplicação DPDORE')}&body=${encodeURIComponent(msg)}">E-mail</a>
          <a class="btn" data-wa href="https://wa.me/?text=${encodeURIComponent(msg)}" target="_blank" rel="noopener noreferrer">WhatsApp</a>${u ? '<button type="button" class="btn" data-file>Enviar a aplicação (ficheiro)</button>' : ''}</div>
        <h4 class="h4 mt-12">Instalar neste computador / telemóvel</h4>
        ${AppShare.deferred ? '<button type="button" class="btn primary" data-install>Instalar aplicação</button>' : `<p class="muted m-0">${matchMedia('(display-mode: standalone)').matches ? 'A aplicação já está instalada.' : u ? 'Chrome / Edge: ícone «Instalar» na barra de endereço (ou menu ⋮ › Instalar). iPhone (Safari): Partilhar › Adicionar ao ecrã principal.' : 'A instalação precisa da versão publicada (endereço https://…).'}</p>`}
        <p class="field-help mt-12">Os dados não seguem com a ligação nem com o ficheiro: cada utilizador entra com a sua conta e os dados passam-se com as cópias de segurança (ou a pasta das cópias).</p>`,
      foot: '<button class="btn primary" type="button" data-close>Fechar</button>' });
    $('[data-copy]', m.el)?.addEventListener('click', async () => { try { await navigator.clipboard.writeText(u); UI.toast('Ligação copiada.'); } catch (_) { $('#shu', m.el).select(); UI.toast('Seleccionada — copie com Ctrl+C.', 'warn'); } });
    $('[data-share]', m.el)?.addEventListener('click', async () => { try { await navigator.share({ title: 'DPDORE', text: msg, ...(u ? { url: u } : {}) }); } catch (e) { if (e.name !== 'AbortError') UI.toast('Não foi possível partilhar.', 'warn'); } });
    $('[data-file]', m.el)?.addEventListener('click', async () => {
      try { const r = await fetch(u, { cache: 'no-store' }); const b = await r.blob(); const f = new File([b], 'DPDORE_Sistema_Gestao_Operacional.html', { type: 'text/html' });
        if (navigator.canShare?.({ files: [f] })) await navigator.share({ files: [f], title: 'DPDORE' }); else Exporter.download(f, f.name);
      } catch (e) { if (e.name !== 'AbortError') UI.toast(`Não foi possível obter o ficheiro: ${e.message}`, 'warn'); } });
    $('[data-install]', m.el)?.addEventListener('click', async () => { const d = AppShare.deferred; if (!d) return; d.prompt(); const c = await d.userChoice.catch(() => null); AppShare.deferred = null; m.close(); if (c?.outcome === 'accepted') UI.toast('Aplicação instalada.'); });
    Store.log('Janela «partilhar / instalar» aberta', 'backup');
  }
};
window.addEventListener('beforeinstallprompt', (e) => { e.preventDefault(); AppShare.deferred = e; });
App.actions['app-share'] = () => AppShare.open();

/* ============ 11x. V9.0 — MUDANÇA OBRIGATÓRIA DA PALAVRA-PASSE NO PRIMEIRO ACESSO ============
   Os utilizadores predefinidos (admin, planeamento, survey) — e qualquer utilizador marcado pelo administrador —
   têm de escolher uma palavra-passe nova logo depois de entrar. A janela não se fecha sem a mudança. */
const PwChange = {
  rule(u) { return u?.role === 'admin' ? { min: 10, txt: 'mínimo 10 caracteres, com letras, números e uma maiúscula ou símbolo', ok: (p) => p.length >= 10 && /[a-z]/i.test(p) && /\d/.test(p) && (/[A-Z]/.test(p) || /[^a-z0-9]/i.test(p)) }
    : { min: 8, txt: 'mínimo 8 caracteres, com letras e números', ok: (p) => p.length >= 8 && /[a-z]/i.test(p) && /\d/.test(p) }; },
  force() {
    const u = Auth.user; if (!u || !u.mustChange || $('[data-pwforce]')) return;
    const R = PwChange.rule(u);
    const m = UI.modal({ title: 'Mude a sua palavra-passe', size: 'narrow',
      body: `<form class="form-grid" data-pwforce novalidate><p class="note full">Primeiro acesso de <b>${esc(u.nome || u.user)}</b> (${esc(u.user)}): por segurança, escolha uma palavra-passe nova (${esc(R.txt)}). A palavra-passe inicial deixa de funcionar.</p>
        <div class="full"><label for="pwn1">Nova palavra-passe</label><input id="pwn1" type="password" autocomplete="new-password" required></div>
        <div class="full"><label for="pwn2">Repetir a nova palavra-passe</label><input id="pwn2" type="password" autocomplete="new-password" required></div>
        <p class="form-error full" role="alert"></p></form>`,
      foot: '<button class="btn" type="button" data-out>Terminar sessão</button><button class="btn primary" type="button" data-ok>Guardar palavra-passe</button>' });
    $$('[data-close]', m.el).forEach((b) => (b.matches('button') ? b.remove() : b.removeAttribute('data-close')));
    m.el.addEventListener('keydown', (e) => { if (e.key === 'Escape') e.stopPropagation(); }, true);
    const err = $('.form-error', m.el);
    const go = () => {
      const a = $('#pwn1', m.el).value, b = $('#pwn2', m.el).value; err.textContent = '';
      if (!R.ok(a)) { err.textContent = `Palavra-passe fraca: ${R.txt}.`; return; }
      if (a !== b) { err.textContent = 'As palavras-passe não coincidem.'; return; }
      const h = pwHash(a); if (h === u.hash || DEFAULT_HASHES.includes(h)) { err.textContent = 'Escolha uma palavra-passe diferente da inicial.'; return; }
      if (u.role === 'admin' && (u.hash === DB.settings.adminHash || DEFAULT_HASHES.includes(DB.settings.adminHash))) DB.settings.adminHash = h; // a palavra-passe de administrador (elevação) passa a ser a nova
      u.hash = h; u.mustChange = false; u.pwChangedAt = nowISO();
      Store.log(`Palavra-passe alterada no primeiro acesso (${u.user})`); Store.save(); m.close(); UI.toast('Palavra-passe guardada. Use-a nos próximos acessos.');
    };
    $('[data-ok]', m.el).addEventListener('click', go);
    $('[data-pwforce]', m.el).addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); go(); } });
    $('[data-out]', m.el).addEventListener('click', () => Auth.logout());
  }
};
{
  const l0 = Auth.login.bind(Auth); Auth.login = (u, p) => { const r = l0(u, p); if (r === true && Auth.user?.mustChange) setTimeout(() => PwChange.force(), 300); return r; };
  const r0 = Auth.restore.bind(Auth); Auth.restore = () => { const r = r0(); if (r && Auth.user?.mustChange) setTimeout(() => PwChange.force(), 600); return r; };
  // qualquer acção enquanto a mudança está pendente volta a mostrar a janela
  document.addEventListener('click', (e) => { if (Auth.user?.mustChange && !e.target.closest('.modal') && !$('[data-pwforce]')) PwChange.force(); }, true);
}

/* ============ 9. ARRANQUE ============ */
function boot() {
  try { Store.load(); } catch (e) {
    console.error(e);
    const p = document.createElement('p'); p.className = 'note error boot-error';
    p.textContent = 'Erro ao carregar os dados guardados neste navegador. Restaure uma cópia de segurança ou limpe o armazenamento deste site.';
    document.body.replaceChildren(p); return;
  }
  App.applySettings();
  Table.bind(); Filters.bind(); Charts.bind(); App.bind(); Planner.bind(); Org.bindDnD(); Appear.bind(); Auth.idle();

  const start = () => {
    $('#login').hidden = true; $('#app').hidden = false;
    $('#whoami').textContent = `${Auth.user.nome} · ${Auth.isAdmin() ? 'Administrador' : 'Utilizador'}`;
    App.applySettings(); // inclui as preferências pessoais do utilizador
    const v = location.hash.slice(1);
    App.view = App.views[v] && Auth.can(v) ? v : (Auth.can('dashboard') ? 'dashboard' : MODULES.map((m) => m[0]).find((m) => App.views[m] && Auth.can(m)) || 'help');
    App.rerender({ keepScroll: false }); App.updateAdminPill();
    const msg = sessionStorage.getItem('dpdore_msg'); if (msg) { sessionStorage.removeItem('dpdore_msg'); UI.toast(msg, 'ok', 6000); }
    Backup.autoSnapshot();
  };

  if (Auth.restore()) { start(); return; }
  $('#login').hidden = false;
  if (sessionStorage.getItem('dpdore_idle')) { sessionStorage.removeItem('dpdore_idle'); $('#loginError').textContent = 'A sessão terminou por inactividade. Entre novamente.'; }
  $('#loginUser').focus();
  $('#loginForm').addEventListener('submit', (e) => {
    e.preventDefault();
    const user = clean($('#loginUser').value, 60), pass = $('#loginPass').value;
    if (!user || !pass) { $('#loginError').textContent = 'Indique o utilizador e a palavra-passe.'; (user ? $('#loginPass') : $('#loginUser')).focus(); return; }
    const r = Auth.login(user, pass);
    if (r !== true) { $('#loginError').textContent = r; $('#loginPass').value = ''; $('#loginPass').focus(); return; }
    $('#loginError').textContent = ''; $('#loginPass').value = ''; start();
  });
}
// V8.9: a base é lida do IndexedDB (assíncrono) antes do arranque; a primeira gravação migra o localStorage
const bootGo = () => StoreX.preload().catch((e) => console.warn(e)).finally(() => { boot(); if (StoreX.mode === 'idb' && StoreX.loadedFrom === 'local' && typeof DB !== 'undefined' && DB) Store.save(); if (StoreX.fromFile && DiskFile.loadedNewer) setTimeout(() => UI.toast(`Dados carregados do ficheiro «${DiskFile.name}» (alterado noutro posto).`, 'ok', 7000), 900); });
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', bootGo); else bootGo();
